/* Code node 2: "Keep only what is new" */
const brief = $('Write the search brief').first().json;
const res = $json;

const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const m = text.match(/\[[\s\S]*\]/);
let found = [];
try { found = m ? JSON.parse(m[0]) : []; } catch (e) { found = []; }

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const knownSet = new Set(brief.known.map(norm));
const idSet = new Set(brief.knownIds || []);

const REGIONS = ["Europe", "North America", "Middle East", "Asia-Pacific", "Africa", "South America"];
const isDate = d => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d);

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 22);
const mkId = (e, i) => {
  const yr = isDate(e.start_date) ? e.start_date.slice(2, 4) : String(new Date().getFullYear()).slice(2);
  let id = slug(e.name) + '-' + yr;
  while (idSet.has(id)) id = slug(e.name) + '-' + yr + '-' + (i + 1);
  idSet.add(id);
  return id;
};

const out = [];
for (const [i, e] of found.entries()) {
  if (!e || !e.name || !e.url) continue;          // no citation, no row
  if (knownSet.has(norm(e.name))) continue;        // we already track it
  const start = isDate(e.start_date) ? e.start_date : null;
  const end = isDate(e.end_date) ? e.end_date : (start || null);
  out.push({
    json: {
      id: mkId(e, i),
      name: String(e.name).slice(0, 120),
      start_date: start,
      end_date: end,
      city: e.city || null,
      country: e.country || null,
      region: REGIONS.includes(e.region) ? e.region : null,
      verticals: Array.isArray(e.verticals) ? e.verticals.slice(0, 3) : [],
      audience_size: Number.isFinite(e.audience_size) ? Math.round(e.audience_size) : null,
      /* No icp_density, seniority, cross_border or strategic. Those four are
         the judgement the score is built from, and they are a person's to
         make. The row lands unscored on purpose. */
      status: 'New',
      dates_confirmed: !!start,
      ai_sourced: true,
      source_url: String(e.url).slice(0, 500),
      discovered_at: new Date().toISOString(),
      note: e.why ? String(e.why).slice(0, 300) : null,
    },
  });
}
return out;

/* Code node 3: "How many" */
const rows = $input.all().filter(i => i.json && i.json.id);
return [{ json: { added: rows.length, events: rows.map(r => r.json.name) } }];
